class Solution:
    def countBalanced(self, low: int, high: int) -> int:
        from functools import lru_cache

        def count_up_to(x: int) -> int:
            if x <= 0:
                return 0
            s = str(x)
            n = len(s)

            # state: position, still tight against x's prefix, a non-zero digit seen,
            # parity of the NEXT position, diff = odd-position sum - even-position sum
            @lru_cache(maxsize=None)
            def dp(pos: int, tight: bool, started: bool, is_odd: bool, diff: int) -> int:
                if pos == n:
                    # a real number (not all zeros) whose two sums are equal
                    return 1 if started and diff == 0 else 0

                limit = int(s[pos]) if tight else 9
                ans = 0
                for d in range(limit + 1):
                    next_tight = tight and (d == limit)
                    if not started:
                        if d == 0:
                            # leading zero: no position consumed
                            ans += dp(pos + 1, next_tight, False, True, diff)
                        else:
                            # first digit is position 1 (odd)
                            ans += dp(pos + 1, next_tight, True, False, diff + d)
                    else:
                        if is_odd:
                            ans += dp(pos + 1, next_tight, True, not is_odd, diff + d)
                        else:
                            ans += dp(pos + 1, next_tight, True, not is_odd, diff - d)
                return ans

            return dp(0, True, False, True, 0)

        # separate cache per bound: the digit string differs
        return count_up_to(high) - count_up_to(low - 1)

