class Solution {
    public long countBalanced(long low, long high) {
        // fresh memo per bound: the digit string differs
        return countUpTo(high) - countUpTo(low - 1);
    }

    private long countUpTo(long x) {
        if (x < 10) return 0; // no two-digit numbers
        String s = Long.toString(x);
        int n = s.length();
        int offset = 72; // max possible difference = 9*8 = 72
        int maxDiff = 2 * offset; // 0..144
        // state: position x tight x started x parity x diff (offset 72)
        Long[][][][][] memo = new Long[n][2][2][2][maxDiff + 1];
        return dfs(0, 1, 0, 1, offset, s, memo, offset);
    }

    private long dfs(int pos, int tight, int started, int parity, int diff,
                     String s, Long[][][][][] memo, int offset) {
        if (pos == s.length()) {
            // a real number whose odd and even sums are equal
            return (started == 1 && diff == offset) ? 1 : 0;
        }
        if (memo[pos][tight][started][parity][diff] != null) {
            return memo[pos][tight][started][parity][diff];
        }
        int limit = (tight == 1) ? s.charAt(pos) - '0' : 9;
        long total = 0;
        for (int d = 0; d <= limit; d++) {
            int newTight = (tight == 1 && d == limit) ? 1 : 0;
            int newStarted = (started == 1 || d != 0) ? 1 : 0;
            int newDiff = diff;
            int newParity = parity;
            // leading zeros consume no position; the first non-zero digit is position 1 (odd)
            if (newStarted == 1) {
                if (parity == 1) { // odd position
                    newDiff = diff + d;
                } else { // even position
                    newDiff = diff - d;
                }
                newParity = 1 - parity;
            }
            total += dfs(pos + 1, newTight, newStarted, newParity, newDiff,
                         s, memo, offset);
        }
        memo[pos][tight][started][parity][diff] = total;
        return total;
    }
}

