#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    long long countBalanced(long long low, long long high) {
        // fresh memo per bound: the digit string differs
        return solve(high) - solve(low - 1);
    }
private:
    long long solve(long long x) {
        if (x <= 0) return 0;
        string s = to_string(x);
        int n = s.size();
        vector<int> dig(n);
        for (int i = 0; i < n; ++i) dig[i] = s[i] - '0';
        const int OFFSET = 100;
        // memo over (position, digits placed so far, diff); tight states are not cached
        vector<vector<vector<long long>>> memo(n + 1, vector<vector<long long>>(n + 1, vector<long long>(2 * OFFSET + 1, -1)));
        function<long long(int, int, int, bool)> dfs = [&](int pos, int len, int diff, bool tight) -> long long {
            if (pos == n) {
                // at least two digits and odd sum == even sum
                return (len >= 2 && diff == 0) ? 1LL : 0LL;
            }
            if (!tight && memo[pos][len][diff + OFFSET] != -1) {
                return memo[pos][len][diff + OFFSET];
            }
            int limit = tight ? dig[pos] : 9;
            long long res = 0;
            for (int d = 0; d <= limit; ++d) {
                int newLen = len;
                int newDiff = diff;
                // leading zero: no position consumed
                if (len == 0 && d == 0) {
                    newLen = 0;
                    newDiff = diff;
                } else {
                    newLen = len + 1;
                    // odd position adds, even position subtracts
                    if (newLen % 2 == 1) {
                        newDiff = diff + d;
                    } else {
                        newDiff = diff - d;
                    }
                }
                res += dfs(pos + 1, newLen, newDiff, tight && (d == limit));
            }
            if (!tight) {
                memo[pos][len][diff + OFFSET] = res;
            }
            return res;
        };
        return dfs(0, 0, 0, true);
    }
};

