var countBalanced = function(low, high) {
    // count(x) = balanced numbers in [0, x]; diff is stored with offset 72 (range -72..72)
    function count(x) {
        if (x < 0) return 0;
        const s = x.toString();
        const n = s.length;
        const digits = s.split('').map(Number);
        // dp[pos][diff][tight][started][parity]
        const dp = new Array(n + 1);
        for (let i = 0; i <= n; i++) {
            dp[i] = new Array(145);
            for (let j = 0; j < 145; j++) {
                dp[i][j] = new Array(2);
                for (let t = 0; t < 2; t++) {
                    dp[i][j][t] = new Array(2);
                    for (let st = 0; st < 2; st++) {
                        dp[i][j][t][st] = new Array(2).fill(-1);
                    }
                }
            }
        }

        // state: position, diff = odd-position sum - even-position sum, tight against x's prefix,
        // started = a non-zero digit placed, parity of the next position
        function dfs(pos, diff, tight, started, parity) {
            if (pos === n) {
                return (started === 1 && diff === 72) ? 1 : 0;
            }
            if (dp[pos][diff][tight][started][parity] !== -1) {
                return dp[pos][diff][tight][started][parity];
            }
            const limit = tight ? digits[pos] : 9;
            let res = 0;
            for (let d = 0; d <= limit; d++) {
                const newTight = tight && (d === limit) ? 1 : 0;
                if (started === 0) {
                    if (d === 0) {
                        // leading zero: no position consumed
                        res += dfs(pos + 1, diff, newTight, 0, 0);
                    } else {
                        const newDiff = diff + d;
                        res += dfs(pos + 1, newDiff, newTight, 1, 1);
                    }
                } else {
                    let newDiff;
                    if (parity === 0) {
                        newDiff = diff + d;
                    } else {
                        newDiff = diff - d;
                    }
                    // odd position adds, even subtracts
                    const newParity = 1 - parity;
                    res += dfs(pos + 1, newDiff, newTight, 1, newParity);
                }
            }
            dp[pos][diff][tight][started][parity] = res;
            return res;
        }

        return dfs(0, 72, 1, 0, 0);
    }

    // fresh memo per bound: the digit string differs
    return count(high) - count(low - 1);
};

