import "strconv"

type state struct {
    pos     int
    diff    int
    started bool
    length  int
    tight   bool
}

// countBalancedUpTo returns the number of balanced integers in [0, x].
func countBalancedUpTo(x int64) int64 {
    if x < 0 {
        return 0
    }
    s := strconv.FormatInt(x, 10)
    n := len(s)
    digits := make([]int, n)
    for i, ch := range s {
        digits[i] = int(ch - '0')
    }
    // state: position, diff = odd sum - even sum, started, digits placed, tight
    memo := make(map[state]int64)
    var dfs func(pos, diff int, started bool, length int, tight bool) int64
    dfs = func(pos, diff int, started bool, length int, tight bool) int64 {
        if pos == n {
            // at least two digits and equal sums
            if started && diff == 0 && length >= 2 {
                return 1
            }
            return 0
        }
        st := state{pos, diff, started, length, tight}
        if v, ok := memo[st]; ok {
            return v
        }
        var res int64
        limit := 9
        if tight {
            limit = digits[pos]
        }
        for d := 0; d <= limit; d++ {
            nextTight := tight && (d == limit)
            // leading zeros consume no position
            nextStarted := started || d != 0
            nextLength := length
            nextDiff := diff
            if nextStarted {
                if !started {
                    // first non‑zero digit → position 1 (odd)
                    nextLength = 1
                    nextDiff = d
                } else {
                    // odd position adds, even position subtracts
                    nextLength = length + 1
                    if nextLength%2 == 1 {
                        nextDiff = diff + d
                    } else {
                        nextDiff = diff - d
                    }
                }
            }
            res += dfs(pos+1, nextDiff, nextStarted, nextLength, nextTight)
        }
        memo[st] = res
        return res
    }
    return dfs(0, 0, false, 0, true)
}

// countBalanced returns the number of balanced integers in [low, high].
func countBalanced(low int64, high int64) int64 {
    return countBalancedUpTo(high) - countBalancedUpTo(low-1)
}
